[InitializeOnLoad] public static class MerchantSceneBuilder {
 const string R="Assets/DuckGame/Maps/V08",G=R+"/Generated",Q="docs/verification/v08/request.txt";static Transform root;static int id;static Material sage,belly,shell,spiral,wood,reed,cloth,ink,ivory,lamp,outline;
 static MerchantSceneBuilder(){EditorApplication.update+=Tick;}
 static void Tick(){if(EditorApplication.isPlaying||EditorApplication.isCompiling||!File.Exists(Q))return;string cmd=File.ReadAllText(Q).Trim();if(cmd=="")return;File.WriteAllText(Q,"");try{if(cmd=="build")Build();else if(cmd=="refine")Refine();else if(cmd=="play")EditorApplication.isPlaying=true;}catch(Exception e){Debug.LogException(e);File.WriteAllText("docs/verification/v08/build-error.txt",e.ToString());}}
 [MenuItem("Duck Game/Maps/Build Merchant Grove v0.8")]
 public static void Build(){Directory.CreateDirectory(G);AssetDatabase.Refresh();string dest=G+"/MerchantGrove.unity";if(File.Exists(dest))throw new Exception("V08 exists; refusing overwrite");var active=UnityEngine.SceneManagement.SceneManager.GetActiveScene();if(active.isDirty&&!EditorSceneManager.SaveScene(active,"docs/verification/v08/baseline/UnsavedScene.unity",true))throw new Exception("Safety save failed");if(!AssetDatabase.CopyAsset("Assets/DuckGame/Maps/V07/Generated/WizardGrove.unity",dest))throw new Exception("Scene copy failed");var scene=EditorSceneManager.OpenScene(dest);foreach(string n in new[]{"Unstaffed merchant counter","Supply crate","Silver jar"})foreach(var t in UnityEngine.Object.FindObjectsOfType<Transform>())if(t.name==n)UnityEngine.Object.DestroyImmediate(t.gameObject);
 sage=Mat("Sage skin",new Color(.53f,.63f,.39f));belly=Mat("Cream belly",new Color(.82f,.77f,.49f));shell=Mat("Warm sand shell",new Color(.80f,.57f,.32f));spiral=Mat("Shell spiral",new Color(.56f,.35f,.19f));wood=Mat("Warm wood",new Color(.39f,.25f,.14f));reed=Mat("Basket wicker",new Color(.68f,.43f,.22f));cloth=Mat("Slate blue canvas",new Color(.39f,.48f,.55f));ink=Mat("Friendly dark eyes",new Color(.13f,.10f,.07f));ivory=Mat("Eye shine",new Color(.98f,.94f,.76f));lamp=Mat("Lantern amber",new Color(1,.76f,.28f));outline=new Material(Shader.Find("Duck Game/Outline URP"));outline.SetFloat("_Width",.005f);outline.SetVector("_Ink",new Vector4(.075f,.07f,.05f,1));AssetDatabase.CreateAsset(outline,G+"/Merchant outline.mat");
 root=new GameObject("Moss the Snail Merchant").transform;
 var foot=Ell("Soft tapered foot",new Vector3(0,.30f,-.30f),new Vector3(.78f,.30f,1.67f),sage);var head=Ell("Upright friendly head",new Vector3(0,.87f,.89f),new Vector3(.57f,.79f,.55f),sage);Ell("Warm throat",new Vector3(0,.70f,1.25f),new Vector3(.43f,.59f,.18f),belly);
 Ell("Round travelling shell",new Vector3(0,1.27f,-.37f),new Vector3(.84f,1.07f,1.03f),shell);
 for(int side=-1;side<=1;side+=2){var points=new List<Vector3>();for(int j=0;j<=120;j++){float a=j/120f*Mathf.PI*4.7f,r=.88f*(1-j/132f);points.Add(new Vector3(side*(.79f+.07f*Mathf.Sin(j/120f*Mathf.PI)),1.28f+Mathf.Sin(a)*r,-.37f+Mathf.Cos(a)*r));}Tube("Carved shell spiral",points.ToArray(),.044f,spiral,8);}
 Transform[] eyes=new Transform[2];for(int i=0;i<2;i++){float x=i==0?-.34f:.34f;var pivot=new GameObject(i==0?"Left eye stalk":"Right eye stalk").transform;pivot.SetParent(root,false);pivot.localPosition=new Vector3(x,1.42f,1.03f);var stalk=Tube("Soft eye stalk",new[]{pivot.localPosition,pivot.localPosition+new Vector3(x*.25f,.48f,.06f),pivot.localPosition+new Vector3(x*.4f,.89f,.02f)},.085f,sage,12);stalk.SetParent(pivot,true);var eye=Ell("Large gentle eye",pivot.localPosition+new Vector3(x*.4f,.91f,.02f),new Vector3(.19f,.25f,.18f),belly);eye.transform.SetParent(pivot,true);var pupil=Ell("Dark pupil",pivot.localPosition+new Vector3(x*.4f,.91f,.173f),new Vector3(.115f,.17f,.065f),ink);pupil.transform.SetParent(pivot,true);var shine=Ell("Eye glint",pivot.localPosition+new Vector3(x*.4f-.035f,.97f,.224f),new Vector3(.037f,.052f,.025f),ivory);shine.transform.SetParent(pivot,true);eyes[i]=pivot;}
 var smile=new List<Vector3>();for(int i=0;i<=24;i++){float x=(i/24f-.5f)*.42f;smile.Add(new Vector3(x,1.15f-.095f*Mathf.Sin(i/24f*Mathf.PI),1.405f));}Tube("Small friendly smile",smile.ToArray(),.022f,ink,8);
 foreach(int side in new[]{-1,1}){Vector3 c=new Vector3(side*1.03f,1.03f,-.30f);Ell("Wicker basket body",c,new Vector3(.35f,.38f,.55f),reed);for(int k=0;k<4;k++){float y=c.y-.23f+k*.15f;var ring=new List<Vector3>();for(int j=0;j<=40;j++){float a=j*Mathf.PI*2/40;ring.Add(new Vector3(c.x+Mathf.Cos(a)*.36f,y,c.z+Mathf.Sin(a)*.55f));}Tube("Woven horizontal band",ring.ToArray(),.035f,wood,7);}for(int k=0;k<8;k++){float a=k*Mathf.PI*2/8;Tube("Woven upright reed",new[]{new Vector3(c.x+Mathf.Cos(a)*.34f,c.y-.28f,c.z+Mathf.Sin(a)*.51f),new Vector3(c.x+Mathf.Cos(a)*.36f,c.y+.30f,c.z+Mathf.Sin(a)*.55f)},.028f,shell,7);}var handle=new List<Vector3>();for(int j=0;j<=24;j++){float a=j*Mathf.PI/24;handle.Add(c+new Vector3(Mathf.Cos(a)*.26f,.30f+Mathf.Sin(a)*.35f,0));}Tube("Basket arched handle",handle.ToArray(),.05f,wood,9);Ell("Packed herb bundle",c+new Vector3(0,.33f,-.15f),new Vector3(.19f,.19f,.23f),sage);Ell("Packed potion",c+new Vector3(0,.35f,.22f),new Vector3(.12f,.18f,.12f),cloth);}
 foreach(float x in new[]{-.88f,.88f})Tube("Canopy curved support",new[]{new Vector3(x,1.30f,-.85f),new Vector3(x,2.62f,-.85f),new Vector3(x,2.73f,-.15f)},.055f,wood,10);
 var v=new List<Vector3>();var tr=new List<int>();for(int z=0;z<=12;z++)for(int x=0;x<=16;x++){float u=x/16f,w=z/12f;v.Add(new Vector3((u-.5f)*2.25f,2.72f-.21f*Mathf.Sin(u*Mathf.PI)-.05f*Mathf.Sin(w*Mathf.PI),-1.17f+w*1.92f));}for(int z=0;z<12;z++)for(int x=0;x<16;x++){int a=z*17+x;tr.AddRange(new[]{a,a+17,a+1,a+1,a+17,a+18,a+1,a+17,a,a+18,a+17,a+1});}MeshObj("Soft slate canvas",v.ToArray(),tr.ToArray(),cloth);
 Tube("Lantern hanging hook",new[]{new Vector3(.88f,2.71f,-.18f),new Vector3(1.38f,2.72f,-.18f),new Vector3(1.38f,2.34f,-.18f)},.045f,wood,9);Ell("Warm lantern glass",new Vector3(1.38f,2.11f,-.18f),new Vector3(.15f,.23f,.15f),lamp);Ell("Lantern cap",new Vector3(1.38f,2.35f,-.18f),new Vector3(.22f,.075f,.22f),wood);Ell("Lantern base",new Vector3(1.38f,1.88f,-.18f),new Vector3(.20f,.06f,.20f),wood);for(int i=0;i<4;i++){float a=i*Mathf.PI/2;Tube("Lantern frame",new[]{new Vector3(1.38f+Mathf.Cos(a)*.16f,1.90f,-.18f+Mathf.Sin(a)*.16f),new Vector3(1.38f+Mathf.Cos(a)*.16f,2.32f,-.18f+Mathf.Sin(a)*.16f)},.021f,wood,6);}
 var col=root.gameObject.AddComponent<CapsuleCollider>();col.center=new Vector3(0,1,-.25f);col.radius=.8f;col.height=2.3f;var idle=root.gameObject.AddComponent<SnailIdle>();idle.body=foot.transform;idle.leftEye=eyes[0];idle.rightEye=eyes[1];var anchor=new GameObject("Trade interaction anchor").transform;anchor.SetParent(root,false);anchor.localPosition=new Vector3(0,1.65f,1.35f);
 var prefab=PrefabUtility.SaveAsPrefabAsset(root.gameObject,G+"/SnailMerchant.prefab");UnityEngine.Object.DestroyImmediate(root.gameObject);var npc=(GameObject)PrefabUtility.InstantiatePrefab(prefab);npc.transform.SetPositionAndRotation(new Vector3(-14,.18f,-16),Quaternion.Euler(0,90,0));var motor=UnityEngine.Object.FindObjectOfType<GooseMotorV04>();var shooter=motor.GetComponent<OrbShooter>();if(shooter==null)shooter=motor.GetComponentInChildren<OrbShooter>();shooter.gameObject.AddComponent<CombatFeedback>();var trade=npc.AddComponent<MerchantTrade>();trade.interactionAnchor=npc.transform.Find("Trade interaction anchor");trade.motor=motor;trade.shooter=shooter;trade.view=motor.view;var sound=new GameObject("Feedback Audio | 8 voices").AddComponent<FeedbackAudio>();sound.clips=new[]{"Shot","Ready","Environment","Target","Purchase","Denied"}.Select(n=>AssetDatabase.LoadAssetAtPath<AudioClip>(R+"/Audio/"+n+".wav")).ToArray();if(!EditorSceneManager.SaveScene(scene,dest))throw new Exception("V08 save failed");AssetDatabase.SaveAssets();File.WriteAllText("docs/verification/v08/build.txt","V08 built; original mesh assets="+id+"; scene="+dest);Debug.Log("V08_BUILD_OK");}
 static void Refine(){
  var path=G+"/SnailMerchant.prefab";var prefab=PrefabUtility.LoadPrefabContents(path);try{
   var filter=prefab.GetComponentsInChildren<MeshFilter>().First(x=>x.name=="Soft slate canvas");var mesh=filter.sharedMesh;var v=new List<Vector3>();var t=new List<int>();int row=17,n=13*17;for(int layer=0;layer<2;layer++)for(int z=0;z<=12;z++)for(int x=0;x<=16;x++){float u=x/16f,w=z/12f;v.Add(new Vector3((u-.5f)*2.25f,2.72f-.21f*Mathf.Sin(u*Mathf.PI)-.05f*Mathf.Sin(w*Mathf.PI)-layer*.035f,-1.17f+w*1.92f));}for(int z=0;z<12;z++)for(int x=0;x<16;x++){int a=z*row+x;t.AddRange(new[]{a,a+row,a+1,a+1,a+row,a+row+1,a+n,a+1+n,a+row+n,a+1+n,a+row+1+n,a+row+n});}for(int x=0;x<16;x++){int a=x,b=12*17+x;t.AddRange(new[]{a,a+1,a+n,a+1,a+1+n,a+n,b,b+n,b+1,b+1,b+n,b+1+n});}for(int z=0;z<12;z++){int a=z*17,b=a+16;t.AddRange(new[]{a,a+n,a+17,a+17,a+n,a+17+n,b,b+17,b+n,b+17,b+17+n,b+n});}mesh.Clear();mesh.vertices=v.ToArray();mesh.triangles=t.ToArray();mesh.RecalculateNormals();mesh.RecalculateBounds();EditorUtility.SetDirty(mesh);
   foreach(var f in prefab.GetComponentsInChildren<MeshFilter>().Where(x=>x.name=="Carved shell spiral")){var m=f.sharedMesh;var vs=m.vertices;for(int j=0;j<vs.Length;j++){float dy=(vs[j].y-1.27f)/1.07f,dz=(vs[j].z+.37f)/1.03f;vs[j].x=Mathf.Sign(vs[j].x)*(.84f*Mathf.Sqrt(Mathf.Max(.04f,1-dy*dy-dz*dz))+.025f);}m.vertices=vs;m.RecalculateNormals();m.RecalculateBounds();EditorUtility.SetDirty(m);}PrefabUtility.SaveAsPrefabAsset(prefab,path);
  }finally{PrefabUtility.UnloadPrefabContents(prefab);}AssetDatabase.SaveAssets();EditorSceneManager.SaveScene(UnityEngine.SceneManagement.SceneManager.GetActiveScene());Debug.Log("V08_REFINE_OK");
 }
 static Material Mat(string n,Color c){var m=new Material(Shader.Find("Duck Game/Toon URP"));m.name=n;m.SetVector("_Tint",new Vector4(c.linear.r,c.linear.g,c.linear.b,1));AssetDatabase.CreateAsset(m,G+"/"+n+".mat");return m;}
 static GameObject MeshObj(string n,Vector3[] v,int[] t,Material mat){var mesh=new Mesh{name=n};mesh.vertices=v;mesh.triangles=t;mesh.RecalculateNormals();mesh.RecalculateBounds();AssetDatabase.CreateAsset(mesh,G+"/MerchantMesh_"+(id++)+".asset");var go=new GameObject(n,typeof(MeshFilter),typeof(MeshRenderer));go.transform.SetParent(root,false);go.GetComponent<MeshFilter>().sharedMesh=mesh;go.GetComponent<MeshRenderer>().sharedMaterials=new[]{mat,outline};return go;}
 static GameObject Ell(string n,Vector3 p,Vector3 s,Material m){var v=new List<Vector3>();var t=new List<int>();int lat=16,lon=24;for(int y=0;y<=lat;y++)for(int x=0;x<=lon;x++){float a=y*Mathf.PI/lat,b=x*Mathf.PI*2/lon;v.Add(p+Vector3.Scale(new Vector3(Mathf.Sin(a)*Mathf.Cos(b),Mathf.Cos(a),Mathf.Sin(a)*Mathf.Sin(b)),s));}for(int y=0;y<lat;y++)for(int x=0;x<lon;x++){int a=y*(lon+1)+x;t.AddRange(new[]{a,a+1,a+lon+1,a+1,a+lon+2,a+lon+1});}return MeshObj(n,v.ToArray(),t.ToArray(),m);}
 static Transform Tube(string n,Vector3[] points,float radius,Material m,int sides){var v=new List<Vector3>();var t=new List<int>();for(int j=0;j<points.Length;j++){Vector3 tangent=(points[Mathf.Min(j+1,points.Length-1)]-points[Mathf.Max(0,j-1)]).normalized;Vector3 right=Vector3.Cross(tangent,Mathf.Abs(tangent.y)>.9f?Vector3.forward:Vector3.up).normalized,up=Vector3.Cross(tangent,right);for(int k=0;k<sides;k++){float a=k*Mathf.PI*2/sides;v.Add(points[j]+radius*(right*Mathf.Cos(a)+up*Mathf.Sin(a)));if(j>0){int c=j*sides+k,prev=j*sides+(k+1)%sides;t.AddRange(new[]{c,c-sides,prev,prev,c-sides,prev-sides});}}}return MeshObj(n,v.ToArray(),t.ToArray(),m).transform;}
}
